import torch
import triton
import triton.language as tl

logger = logging.getLogger(__name__)

_BLOCK_R = 32
_GATHER_R = 8
_GATHER_C = 512
_META_W = 128
_FAST_NW_SMALL = 32
_FAST_NW_LARGE = 128
_FAST_NW_SWITCH_WORDS = 32768
_FAST_NUM_WARPS = 2


@triton.jit
def _to_sss_kernel(
    dense_ptr,
    packed_ptr,
    meta_ptr,
    flag_ptr,
    nrows,
    ncols,
    meta_nrows,
    stride0,
    stride1,
    BLOCK_R: tl.constexpr,
    BLOCK_META: tl.constexpr,
    PER_META: tl.constexpr,
    KSPARSE: tl.constexpr,
    GROUP: tl.constexpr,  # reorder row group: 32 for int16 meta, 16 for int32
    INTERWEAVE: tl.constexpr,  # reorder row interleave: 4 for int16 meta, 2 for int32
    META_I32: tl.constexpr,
):
    """Fast path: logical row-major input with a logically valid pattern."""
    NG: tl.constexpr = PER_META // KSPARSE  # groups per metadata element
    BLOCK_C: tl.constexpr = BLOCK_META * PER_META
    NGRP: tl.constexpr = BLOCK_C // KSPARSE  # groups per row-block

    pid_r = tl.program_id(0)
    pid_c = tl.program_id(1)

    rows = pid_r * BLOCK_R + tl.arange(0, BLOCK_R)
    cols = pid_c * BLOCK_C + tl.arange(0, BLOCK_C)
    rmask = rows < nrows
    cmask = cols < ncols
    load_mask = rmask[:, None] & cmask[None, :]

    # Masked-out columns read as +0 so they count as pruned slots and can never
    # create a spurious validity failure.
    V = tl.load(
        dense_ptr + rows[:, None] * stride0 + cols[None, :] * stride1,
        mask=load_mask,
        other=0,
    )
    # A group participates in the validity check only when its whole metadata
    # element is inside the tensor (BLOCK_C is a multiple of PER_META and
    # ncols % PER_META == 0, so groups are never partially in range).
    gidx = tl.arange(0, NGRP)
    inrange = rmask[:, None] & (pid_c * BLOCK_C + gidx * KSPARSE < ncols)[None, :]

    if KSPARSE == 4:
        # Direct per-slot loads.  gcu400 miscompiles the
        # reshape -> split -> split de-interleave of a (BR, NGRP, 4) tile: the
        # fourth slot reads garbage (standalone probe: v3 = [5,13,69,77] where
        # [3,7,11,15] is expected), so every valid 2:4 fp16/bf16/int8 input was
        # rejected as pattern-invalid.  Four strided loads give exact values
        # and keep the value gather a pure tl.where tree (bit exact, no add).
        base = dense_ptr + rows[:, None] * stride0
        gcol = (pid_c * BLOCK_C + gidx * KSPARSE)[None, :]
        c0c = gcol
        c1c = gcol + 1
        c2c = gcol + 2
        c3c = gcol + 3
        v0 = tl.load(base + c0c * stride1, mask=inrange & (c0c < ncols), other=0)
        v1 = tl.load(base + c1c * stride1, mask=inrange & (c1c < ncols), other=0)
        v2 = tl.load(base + c2c * stride1, mask=inrange & (c2c < ncols), other=0)
        v3 = tl.load(base + c3c * stride1, mask=inrange & (c3c < ncols), other=0)
        n0 = v0 != 0
        n1 = v1 != 0
        n2 = v2 != 0
        n3 = v3 != 0
        cnt = n0.to(tl.int32) + n1.to(tl.int32) + n2.to(tl.int32) + n3.to(tl.int32)
        c0 = tl.where(n0, 0, tl.where(n1, 1, tl.where(n2, 2, 3)))
        c1 = tl.where(
            n0 & (c0 != 0),
            0,
            tl.where(n1 & (c0 != 1), 1, tl.where(n2 & (c0 != 2), 2, 3)),
        )
        val0 = tl.where(c0 == 0, v0, tl.where(c0 == 1, v1, tl.where(c0 == 2, v2, v3)))
        val1 = tl.where(c1 == 0, v0, tl.where(c1 == 1, v1, tl.where(c1 == 2, v2, v3)))
        pl = tl.reshape(tl.join(val0, val1), (BLOCK_R, BLOCK_C // 2))
        q = c0 | (c1 << 2)  # (BLOCK_R, NGRP)
    else:
        Vr = tl.reshape(V, (BLOCK_R, NGRP, KSPARSE))
        v0, v1 = tl.split(tl.reshape(Vr, (BLOCK_R, NGRP, 1, 2)))
        v0 = tl.reshape(v0, (BLOCK_R, NGRP))
        v1 = tl.reshape(v1, (BLOCK_R, NGRP))
        n0 = v0 != 0
        n1 = v1 != 0
        cnt = n0.to(tl.int32) + n1.to(tl.int32)
        c0 = tl.where(n0, 0, 1)
        pl = tl.reshape(tl.where(c0 == 0, v0, v1), (BLOCK_R, BLOCK_C // 2))
        # KSPARSE == 2 retains one of a pair; the reference duplicates the slot
        # pattern to the 4-slot form, so the node is 4 (even col) or 14 (odd).
        q = (2 * c0) | ((2 * c0 + 1) << 2)

    bad = (cnt != (KSPARSE // 2)) & inrange
    if tl.max(tl.reshape(bad.to(tl.int32), (BLOCK_R * NGRP,)), axis=0) > 0:
        tl.atomic_or(flag_ptr, 1)

    pc = pid_c * (BLOCK_C // 2) + tl.arange(0, BLOCK_C // 2)
    poff = rows[:, None] * (ncols // 2) + pc[None, :]
    pmask = rmask[:, None] & (pc < ncols // 2)[None, :]
    tl.store(packed_ptr + poff, pl, mask=pmask)

    # ---- metadata node word: NG nibbles, low nibble first ----
    # Assemble by shifting and summing over the group axis: the four-bit fields
    # are disjoint, so the sum equals the OR.  This avoids the reshape/split
    # chains gcu400 miscompiles (same family as the value de-interleave above;
    # the int8 NG == 8 chain produced wrong metadata), and the fields are
    # widened to uint32 before shifting so the top nibble never touches signed
    # overflow.
    qq = tl.reshape(q.to(tl.uint32), (BLOCK_R, BLOCK_META, NG))
    shifts = (4 * tl.arange(0, NG)).to(tl.uint32)
    w = tl.sum(qq << shifts[None, None, :], axis=2)

    # ---- ColumnMajorInterleaved<2> reorder (cutlass::reorder_meta) ----
    m = rows[:, None]
    k = pid_c * BLOCK_META + tl.arange(0, BLOCK_META)[None, :]
    dr0 = (m // GROUP) * GROUP + (m % 8) * INTERWEAVE + (m % GROUP) // 8
    odd_r = (dr0 % 2) == 1
    odd_c = (k % 2) == 1
    drow = tl.where(odd_r & (~odd_c), dr0 - 1, tl.where((~odd_r) & odd_c, dr0 + 1, dr0))
    dcol = tl.where(odd_r & (~odd_c), k + 1, tl.where((~odd_r) & odd_c, k - 1, k))
    flat = (dcol // 2) * (2 * meta_nrows) + drow * 2 + (dcol % 2)

    store_mask = rmask[:, None] & (k < ncols // PER_META)
    if META_I32:
        tl.store(meta_ptr + flat, w.to(tl.int32, bitcast=True), mask=store_mask)
    else:
        tl.store(
            meta_ptr + flat, w.to(tl.uint16).to(tl.int16, bitcast=True), mask=store_mask
        )


@triton.jit
def _row_counts(
    src, counts, nrows, ncols, stride0, stride1, BR: tl.constexpr, CHUNK: tl.constexpr
):
    """Retained-element count of every logical row."""
    rows = tl.program_id(0) * BR + tl.arange(0, BR)
    rmask = rows < nrows
    tot = tl.zeros((BR,), dtype=tl.int32)
    for c0 in range(0, ncols, CHUNK):
        cols = c0 + tl.arange(0, CHUNK)
        m = rmask[:, None] & (cols < ncols)[None, :]
        v = tl.load(
            src + rows[:, None] * stride0 + cols[None, :] * stride1, mask=m, other=0
        )
        tot += tl.sum(((v != 0) & m).to(tl.int32), axis=1)
    tl.store(counts + rows, tot, mask=rmask)


@triton.jit
def _scan_counts(counts, base, flag_ptr, nrows, ncols, BLK: tl.constexpr):
    """Exclusive prefix sum of the row counts plus the reference's `.view()` check.

    Rows may hold different numbers of retained elements (the compact-order
    fixture does), so the payload destination needs the true flat rank
    base[row] + within-row rank.  `.view(nrows, ncols/2)` only succeeds when the
    grand total is exact.
    """
    carry = 0
    for r0 in range(0, nrows, BLK):
        offs = r0 + tl.arange(0, BLK)
        m = offs < nrows
        c = tl.load(counts + offs, mask=m, other=0)
        incl = tl.cumsum(c, axis=0)
        tl.store(base + offs, incl - c + carry, mask=m)
        carry += tl.sum(c, axis=0)
    if carry != nrows * (ncols // 2):
        tl.atomic_or(flag_ptr, 1)


@triton.jit
def _pack_logical(
    src,
    packed,
    base,
    flag_ptr,
    nrows,
    ncols,
    stride0,
    stride1,
    BR: tl.constexpr,
    CHUNK: tl.constexpr,
):
    """masked_select over the LOGICAL row-major order, using the scan bases."""
    if tl.load(flag_ptr) != 0:
        # The total disagrees with nrows*ncols/2, so the reference's `.view()`
        # raises; the buffer must be left untouched.
        return
    rows = tl.program_id(0) * BR + tl.arange(0, BR)
    rmask = rows < nrows
    b = tl.load(base + rows, mask=rmask, other=0)
    for c0 in range(0, ncols, CHUNK):
        cols = c0 + tl.arange(0, CHUNK)
        m = rmask[:, None] & (cols < ncols)[None, :]
        v = tl.load(
            src + rows[:, None] * stride0 + cols[None, :] * stride1, mask=m, other=0
        )
        nz = (v != 0) & m
        rank = tl.cumsum(nz.to(tl.int32), axis=1) - 1 + b[:, None]
        tl.store(packed + rank, v, mask=nz)


@triton.jit
def _meta_compact(
    dense_ptr,
    meta_ptr,
    flag_ptr,
    nrows,
    ncols,
    meta_nrows,
    meta_ncols,
    stride0,
    stride1,
    BLOCK_W: tl.constexpr,
    PER_META: tl.constexpr,
    KSPARSE: tl.constexpr,
    GROUP: tl.constexpr,
    INTERWEAVE: tl.constexpr,
    META_I32: tl.constexpr,
):
    """Compact-order metadata + group validity (dim0 is the innermost strided dim)."""
    NGB: tl.constexpr = PER_META // KSPARSE
    total = meta_nrows * meta_ncols
    w = tl.program_id(0) * BLOCK_W + tl.arange(0, BLOCK_W)
    wm = w < total
    m = w // meta_ncols
    k = w % meta_ncols
    kk = w[:, None] * PER_META + tl.arange(0, PER_META)[None, :]
    row = kk % nrows
    col = kk // nrows
    v = tl.load(dense_ptr + row * stride0 + col * stride1, mask=wm[:, None], other=0)
    g = tl.reshape(v, (BLOCK_W, NGB, KSPARSE))
    nz = g != 0
    cnt = tl.sum(nz.to(tl.int32), axis=2)
    # Words past the last metadata element load as zero (cnt == 0) and would
    # otherwise read as a spurious pattern violation, so the validity check is
    # limited to the in-range words.
    bad = (cnt != (KSPARSE // 2)) & wm[:, None]
    if tl.max(tl.max(bad.to(tl.int32), axis=1), axis=0) > 0:
        tl.atomic_or(flag_ptr, 1)

    slot = tl.reshape(tl.arange(0, KSPARSE), (1, 1, KSPARSE))
    c0 = tl.min(tl.where(nz, slot, KSPARSE), axis=2)
    c1 = tl.min(tl.where(nz & (slot != c0[:, :, None]), slot, KSPARSE), axis=2)
    if KSPARSE == 4:
        mc0, mc1 = c0, c1
    else:
        mc0 = 2 * c0
        mc1 = 2 * c0 + 1
    q = (mc0 | (mc1 << 2)).to(tl.uint32)
    q3 = tl.reshape(q, (BLOCK_W, NGB))
    gidx = tl.arange(0, NGB)
    word = tl.zeros((BLOCK_W,), dtype=tl.uint32)
    for gidx_i in tl.static_range(NGB):
        word = word | (
            tl.sum(tl.where(gidx[None, :] == gidx_i, q3, 0), axis=1) << (4 * gidx_i)
        )

    dr0 = (m // GROUP) * GROUP + (m % 8) * INTERWEAVE + (m % GROUP) // 8
    odd_r = (dr0 % 2) == 1
    odd_c = (k % 2) == 1
    drow = tl.where(odd_r & (~odd_c), dr0 - 1, tl.where((~odd_r) & odd_c, dr0 + 1, dr0))
    dcol = tl.where(odd_r & (~odd_c), k + 1, tl.where((~odd_r) & odd_c, k - 1, k))
    flat = (dcol // 2) * (2 * meta_nrows) + drow * 2 + (dcol % 2)
    if META_I32:
        tl.store(meta_ptr + flat, word.to(tl.int32, bitcast=True), mask=wm)
    else:
        tl.store(
            meta_ptr + flat, word.to(tl.uint16).to(tl.int16, bitcast=True), mask=wm
        )


def _compact_order(strides):
    """True when the mask buffer iterates dim0 fastest (the `transposed` layout)."""
    return 0 < strides[0] < strides[1]


def _to_sparse_semi_structured_baseline(dense):
    """Pre-optimization implementation, used as the fallback kernel.

    Used directly by the public entry point for every input the optimized
    int64-word kernel does not cover (compact-order buffers, element stride
    != 1, odd meta width).
    """
    logger.debug("GEMS_ENFLAMETO_SPARSE_SEMI_STRUCTURED BASELINE")
    if not isinstance(dense, torch.Tensor):
        raise RuntimeError(
            "_to_sparse_semi_structured: dense argument must be a Tensor"
        )
    if dense.dim() != 2:
        raise RuntimeError(
            "_to_sparse_semi_structured: Expected dense argument to be 2D tensor, "
            "got {} dims".format(dense.dim())
        )

    dt = dense.dtype
    if dt == torch.int8:
        per_meta, ksparse = 32, 4
        meta_dtype = torch.int32
        row_align = 16
        group, interweave = 16, 2
        meta_i32 = True
    elif dt == torch.float16 or dt == torch.bfloat16:
        per_meta, ksparse = 16, 4
        meta_dtype = torch.int16
        row_align = 32
        group, interweave = 32, 4
        meta_i32 = False
    elif dt == torch.float32:
        per_meta, ksparse = 8, 2
        meta_dtype = torch.int16
        row_align = 32
        group, interweave = 32, 4
        meta_i32 = False
    else:
        raise RuntimeError(
            "_to_sparse_semi_structured: Invalid dense argument datatype "
            "{} encountered".format(dt)
        )

    nrows, ncols = dense.shape
    if nrows % row_align != 0:
        raise RuntimeError(
            "_to_sparse_semi_structured: Number of rows of dense matrix must be "
            "divisible by {}, but it is {}".format(row_align, nrows)
        )
    if ncols % per_meta != 0:
        raise RuntimeError(
            "_to_sparse_semi_structured: Number of columns of dense matrix must be "
            "divisible by {}, but it is {}".format(per_meta, ncols)
        )

    packed = torch.empty((nrows, ncols // 2), dtype=dt, device=dense.device)
    meta_ncols = ncols // per_meta
    meta = torch.empty((nrows, meta_ncols), dtype=meta_dtype, device=dense.device)
    if packed.numel() == 0 or meta.numel() == 0:
        return packed, meta

    flag = torch.zeros(1, dtype=torch.int32, device=dense.device)
    strides = dense.stride()
    compact = _compact_order(strides)

    if compact:
        # The payload is a logical masked_select while the metadata follows the
        # compact order, so the two are produced by separate kernels.  Rows may
        # hold different retained counts, so the payload needs true flat ranks.
        counts = torch.empty(nrows, dtype=torch.int32, device=dense.device)
        base = torch.empty(nrows, dtype=torch.int32, device=dense.device)
        _row_counts[(triton.cdiv(nrows, _GATHER_R),)](
            dense,
            counts,
            nrows,
            ncols,
            strides[0],
            strides[1],
            BR=_GATHER_R,
            CHUNK=_GATHER_C,
        )
        _scan_counts[(1,)](
            counts,
            base,
            flag,
            nrows,
            ncols,
            BLK=min(256, triton.next_power_of_2(max(nrows, 2))),
        )
        _pack_logical[(triton.cdiv(nrows, _GATHER_R),)](
            dense,
            packed,
            base,
            flag,
            nrows,
            ncols,
            strides[0],
            strides[1],
            BR=_GATHER_R,
            CHUNK=_GATHER_C,
        )
        _meta_compact[(triton.cdiv(meta.numel(), _META_W),)](
            dense,
            meta,
            flag,
            nrows,
            ncols,
            nrows,
            meta_ncols,
            strides[0],
            strides[1],
            BLOCK_W=_META_W,
            PER_META=per_meta,
            KSPARSE=ksparse,
            GROUP=group,
            INTERWEAVE=interweave,
            META_I32=meta_i32,
        )
    else:
        block_meta = max(1, 64 // per_meta)
        block_c = block_meta * per_meta
        grid = (triton.cdiv(nrows, _BLOCK_R), triton.cdiv(ncols, block_c))
        _to_sss_kernel[grid](
            dense,
            packed,
            meta,
            flag,
            nrows,
            ncols,
            nrows,
            strides[0],
            strides[1],
            BLOCK_R=_BLOCK_R,
            BLOCK_META=block_meta,
            PER_META=per_meta,
            KSPARSE=ksparse,
            GROUP=group,
            INTERWEAVE=interweave,
            META_I32=meta_i32,
            num_warps=4,
        )

    if flag.item() != 0:
        raise RuntimeError(
            "_to_sparse_semi_structured: dense argument does not match "
            "{} sparsity pattern".format("1:2" if ksparse == 2 else "2:4")
        )
    return packed, meta


@triton.jit
def _group_q(
    lo32, hi32, ELEM_BITS: tl.constexpr, KSPARSE: tl.constexpr, NEG0: tl.constexpr
):
    """Slot codes/values of the group whose slots live in (lo32[, hi32]).

    ELEM_BITS==8:  the four slots are the four bytes of lo32 (KSPARSE==4).
    ELEM_BITS==16: slots are the 16-bit lanes of (lo32, hi32), KSPARSE==4.
    ELEM_BITS==32: slots are (lo32, hi32), KSPARSE==2.
    Returns (q, cnt, v0, v1): the 4-bit slot code, the nonzero count, and the
    two retained fields as zero-extended uint32 bit patterns (bit-exact).
    """
    if ELEM_BITS == 16:
        s0 = lo32 & 0xFFFF
        s1 = (lo32 >> 16) & 0xFFFF
        s2 = hi32 & 0xFFFF
        s3 = (hi32 >> 16) & 0xFFFF
    elif ELEM_BITS == 8:
        s0 = lo32 & 0xFF
        s1 = (lo32 >> 8) & 0xFF
        s2 = (lo32 >> 16) & 0xFF
        s3 = (lo32 >> 24) & 0xFF
    else:
        s0 = lo32
        s1 = hi32
        s2 = s0
        s3 = s1
    n0 = (s0 != 0) & (s0 != NEG0)
    n1 = (s1 != 0) & (s1 != NEG0)
    if KSPARSE == 4:
        n2 = (s2 != 0) & (s2 != NEG0)
        n3 = (s3 != 0) & (s3 != NEG0)
        cnt = n0.to(tl.int32) + n1.to(tl.int32) + n2.to(tl.int32) + n3.to(tl.int32)
        c0 = tl.where(n0, 0, tl.where(n1, 1, tl.where(n2, 2, 3)))
        c1 = tl.where(
            n0 & (c0 != 0),
            0,
            tl.where(n1 & (c0 != 1), 1, tl.where(n2 & (c0 != 2), 2, 3)),
        )
        v0 = tl.where(c0 == 0, s0, tl.where(c0 == 1, s1, tl.where(c0 == 2, s2, s3)))
        v1 = tl.where(c1 == 0, s0, tl.where(c1 == 1, s1, tl.where(c1 == 2, s2, s3)))
        q = c0 | (c1 << 2)
    else:
        cnt = n0.to(tl.int32) + n1.to(tl.int32)
        c0 = tl.where(n0, 0, 1)
        v0 = tl.where(c0 == 0, s0, s1)
        v1 = v0
        q = (2 * c0) | ((2 * c0 + 1) << 2)
    return q, cnt, v0, v1


@triton.jit
def _to_sss_i64_kernel(
    g_ptr,
    packed_ptr,
    meta_ptr,
    flag_ptr,
    nrows,
    words_per_row,
    wstride0,
    meta_nrows,
    meta_ncols,
    BLOCK_R: tl.constexpr,
    NW: tl.constexpr,
    KSPARSE: tl.constexpr,
    GROUP: tl.constexpr,
    INTERWEAVE: tl.constexpr,
    META_I32: tl.constexpr,
    ELEM_BITS: tl.constexpr,
):
    """Optimized int64-word kernel for row-major inputs (see module docstring)."""
    WPM: tl.constexpr = 4  # int64 words per meta word
    GPW: tl.constexpr = 64 // (KSPARSE * ELEM_BITS)  # groups per int64 word
    NG: tl.constexpr = WPM * GPW  # groups per meta word
    BM: tl.constexpr = (NW * GPW) // NG  # meta words per row-tile

    pid_r = tl.program_id(0)
    pid_c = tl.program_id(1)

    if ELEM_BITS == 16:
        NEG0: tl.constexpr = 0x8000
    elif ELEM_BITS == 32:
        NEG0: tl.constexpr = 0x80000000
    else:
        NEG0: tl.constexpr = 0x100  # int8 has no negative zero; never matches

    # ---- pass A: packed payload + validity flag (input order) ----
    rows = pid_r * BLOCK_R + tl.arange(0, BLOCK_R)
    widx = pid_c * NW + tl.arange(0, NW)
    rmask = rows < nrows
    wmask = rmask[:, None] & (widx < words_per_row)[None, :]

    G = tl.load(g_ptr + rows[:, None] * wstride0 + widx[None, :], mask=wmask, other=0)
    Gu = G.to(tl.uint64, bitcast=True)
    lo32 = (Gu & 0xFFFFFFFF).to(tl.uint32)
    hi32 = (Gu >> 32).to(tl.uint32)

    qa, cnta, va0, va1 = _group_q(lo32, hi32, ELEM_BITS, KSPARSE, NEG0)
    if GPW == 1:
        if ELEM_BITS == 16:
            P = va0 | (va1 << 16)
        else:
            P = va0
        bad = (cnta != (KSPARSE // 2)) & wmask
    else:
        qb, cntb, vb0, vb1 = _group_q(hi32, lo32, 8, 4, 0x100)
        P = va0 | (va1 << 8) | (vb0 << 16) | (vb1 << 24)
        bad = ((cnta != 2) | (cntb != 2)) & wmask

    if tl.max(tl.reshape(bad.to(tl.int32), (BLOCK_R * NW,)), axis=0) > 0:
        tl.atomic_or(flag_ptr, 1)

    tl.store(
        packed_ptr + rows[:, None] * words_per_row + widx[None, :],
        P.to(tl.int32, bitcast=True),
        mask=wmask,
    )

    # ---- pass B: metadata from the codes already in registers ----
    # The ColumnMajorInterleaved<2> permutation maps the (BLOCK_R, BM) tile
    # onto itself (the row swizzle stays inside the GROUP block and the
    # parity swap exchanges adjacent column pairs), so the tile lanes only
    # need the reordered store address, never a data shuffle.
    rl = tl.arange(0, BLOCK_R)
    dr0l = (rl // GROUP) * GROUP + ((rl % GROUP) % 8) * INTERWEAVE + (rl % GROUP) // 8
    kl = tl.arange(0, BM)
    dr0t = tl.broadcast_to(dr0l[:, None], (BLOCK_R, BM))
    klt = tl.broadcast_to(kl[None, :], (BLOCK_R, BM))
    b = (dr0t ^ klt) & 1
    drowl = dr0t ^ b
    dcoll = klt ^ b

    if GPW == 1:
        contrib = qa.to(tl.uint32) << (4 * (widx % WPM))[None, :]
    else:
        contrib = (qa.to(tl.uint32) << (8 * (widx % WPM))[None, :]) | (
            qb.to(tl.uint32) << (8 * (widx % WPM) + 4)[None, :]
        )
    wword = tl.sum(tl.reshape(contrib, (BLOCK_R, BM, WPM)), axis=2)

    drow = pid_r * BLOCK_R + drowl
    dcol = dcoll + pid_c * BM
    flat = (dcol // 2) * (2 * meta_nrows) + drow * 2 + (dcol & 1)
    smask = tl.broadcast_to(rmask[:, None], (BLOCK_R, BM)) & (dcol < meta_ncols)
    if META_I32:
        tl.store(meta_ptr + flat, wword.to(tl.int32, bitcast=True), mask=smask)
    else:
        tl.store(
            meta_ptr + flat, wword.to(tl.uint16).to(tl.int16, bitcast=True), mask=smask
        )


def _to_sss_fast(dense):
    """Launch the optimized int64-word kernel; returns None when inapplicable.

    Every rejection here falls through to ``_to_sparse_semi_structured_baseline``
    which re-validates and raises the reference's error messages, so no input
    class loses its semantics.  Pattern-invalid inputs raise from this path
    with the reference's message (never silently fall back).
    """
    if not isinstance(dense, torch.Tensor) or dense.dim() != 2:
        return None
    dt = dense.dtype
    if dt == torch.int8:
        per_meta, ksparse, meta_dtype, row_align = 32, 4, torch.int32, 16
        group, interweave, meta_i32, elem_bits = 16, 2, True, 8
    elif dt == torch.float16 or dt == torch.bfloat16:
        per_meta, ksparse, meta_dtype, row_align = 16, 4, torch.int16, 32
        group, interweave, meta_i32, elem_bits = 32, 4, False, 16
    elif dt == torch.float32:
        per_meta, ksparse, meta_dtype, row_align = 8, 2, torch.int16, 32
        group, interweave, meta_i32, elem_bits = 32, 4, False, 32
    else:
        return None
    nrows, ncols = dense.shape
    if nrows == 0 or ncols == 0:
        return None
    if nrows % row_align != 0 or ncols % per_meta != 0:
        return None
    if (ncols // per_meta) % 2 != 0:
        # Odd meta width: keep the reference's exact store semantics verbatim.
        return None
    strides = dense.stride()
    if strides[1] != 1 or _compact_order(strides):
        return None
    try:
        xi64 = dense.view(torch.int64)
    except (RuntimeError, ValueError):
        return None

    words_per_row = xi64.shape[1]
    meta_ncols = ncols // per_meta
    packed = torch.empty((nrows, ncols // 2), dtype=dt, device=dense.device)
    pi32 = packed.view(torch.int32)
    meta = torch.empty((nrows, meta_ncols), dtype=meta_dtype, device=dense.device)
    flag = torch.zeros(1, dtype=torch.int32, device=dense.device)

    nw = (
        _FAST_NW_SMALL
        if nrows * words_per_row <= _FAST_NW_SWITCH_WORDS
        else _FAST_NW_LARGE
    )
    grid = (triton.cdiv(nrows, _BLOCK_R), triton.cdiv(words_per_row, nw))
    _to_sss_i64_kernel[grid](
        xi64,
        pi32,
        meta,
        flag,
        nrows,
        words_per_row,
        xi64.stride(0),
        nrows,
        meta_ncols,
        BLOCK_R=_BLOCK_R,
        NW=nw,
        KSPARSE=ksparse,
        GROUP=group,
        INTERWEAVE=interweave,
        META_I32=meta_i32,
        ELEM_BITS=elem_bits,
        num_warps=_FAST_NUM_WARPS,
    )
    if flag.item() != 0:
        raise RuntimeError(
            "_to_sparse_semi_structured: dense argument does not match "
            "{} sparsity pattern".format("1:2" if ksparse == 2 else "2:4")
        )
    return packed, meta


def to_sparse_semi_structured(dense):
    logger.debug("GEMS_ENFLAME_GCU400 TO_SPARSE_SEMI_STRUCTURED")
    result = _to_sss_fast(dense)
    if result is not None:
        return result
    return _to_sparse_semi_structured_baseline(dense)
